using System;using System.Diagnostics;using System.IO;using System.Reflection;using System.Text;using System.Threading;
namespace PZ3D {
 internal static class DuplicateLaunchTests {
  static int checks;static string fixture;
  static void Check(bool value,string name){if(!value)throw new Exception("FAIL "+name);checks++;Console.WriteLine("PASS "+name);}
  static void Until(Func<bool> ready){var deadline=DateTime.UtcNow.AddSeconds(8);while(!ready()){if(DateTime.UtcNow>deadline)throw new Exception("owned holder ready timeout");Thread.Sleep(20);}}
  static Process Hold(string root,string signal){Directory.CreateDirectory(root);string ready=Path.Combine(fixture,signal+".ready"),stop=Path.Combine(fixture,signal+".stop");var start=new ProcessStartInfo(typeof(DuplicateLaunchTests).Assembly.Location,"--hold \""+root+"\" \""+ready+"\" \""+stop+"\""){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden};var child=Process.Start(start);Until(()=>File.Exists(ready));return child;}
  static void Stop(Process child,string signal){File.WriteAllText(Path.Combine(fixture,signal+".stop"),"");if(!child.WaitForExit(5000))throw new Exception("owned holder failed to stop");child.Dispose();}
  static bool Try(string root,out IDisposable lease){var method=typeof(NativeApplyGuard).GetMethod("TryInstance",BindingFlags.Static|BindingFlags.NonPublic);Check(method!=null,"normal startup has nonblocking instance acquisition");object[] args={root,null};bool acquired=(bool)method.Invoke(null,args);lease=args[1] as IDisposable;return acquired;}
  static int Run(string root,Func<int> start,Func<bool> activate,Action<string> notice){var type=typeof(NativeApplyGuard).Assembly.GetType("PZ3D.LauncherWindowActivation");Check(type!=null,"normal startup has existing-window and handoff decision");var method=type.GetMethod("Run",BindingFlags.Static|BindingFlags.NonPublic,null,new[]{typeof(string),typeof(Func<int>),typeof(Func<bool>),typeof(Action<string>)},null);Check(method!=null,"startup decision can preserve original worker lease");try{return (int)method.Invoke(null,new object[]{root,start,activate,notice});}catch(TargetInvocationException error){throw error.InnerException;}}
  static void Decisions(string root){int started=0,activated=0,notices=0;using(var holder=Hold(root,"activate")){try{var watch=Stopwatch.StartNew();int result=Run(root,()=>{started++;return 9;},()=>{activated++;return true;},message=>notices++);Check(result==0&&started==0&&activated==1&&notices==0&&watch.ElapsedMilliseconds<1000,"existing UI duplicate activates promptly without launching or showing an error");Check(!holder.HasExited,"duplicate launch leaves old process alive");}finally{Stop(holder,"activate");}}
   using(var holder=Hold(root,"handoff")){try{var release=new Thread(()=>{Thread.Sleep(250);File.WriteAllText(Path.Combine(fixture,"handoff.stop"),"");});release.Start();var watch=Stopwatch.StartNew();int result=Run(root,()=>{started++;return 7;},()=>false,message=>notices++);release.Join();Check(result==7&&started==1&&notices==0&&watch.ElapsedMilliseconds>=150&&watch.ElapsedMilliseconds<3000,"no-UI handoff waits for worker release then starts normally");}finally{Stop(holder,"handoff");}}
   using(var holder=Hold(root,"timeout")){try{var watch=Stopwatch.StartNew();string warning=null;int result=Run(root,()=>{started++;return 9;},()=>false,message=>{notices++;warning=message;});Check(result==0&&started==1&&notices==1&&!string.IsNullOrWhiteSpace(warning)&&watch.ElapsedMilliseconds>=9000&&watch.ElapsedMilliseconds<13000,"unreleased handoff exits with friendly notice instead of unhandled IOException");}finally{Stop(holder,"timeout");}}
   activated=0;int normal=Run(root,()=>{started++;return 11;},()=>{activated++;return false;},message=>notices++);Check(normal==11&&started==2&&activated==0&&notices==1,"free installation starts once without probing other windows");IDisposable final;Check(Try(root,out final),"startup delegate return releases installation lease");final.Dispose();final.Dispose();
  }
  static object Window(int pid,string image,long handle,bool visible,bool minimized,string title){var type=typeof(NativeApplyGuard).Assembly.GetType("PZ3D.LauncherWindowCandidate");Check(type!=null,"window candidate records exact image and owning PID");return Activator.CreateInstance(type,BindingFlags.Instance|BindingFlags.NonPublic,null,new object[]{pid,image,new IntPtr(handle),visible,minimized,title},null);}
  static bool Activate(string root,object[] windows,Func<object,bool> verify,Func<IntPtr,bool> restore,Func<IntPtr,bool> foreground){var type=typeof(NativeApplyGuard).Assembly.GetType("PZ3D.LauncherWindowActivation");var candidate=typeof(NativeApplyGuard).Assembly.GetType("PZ3D.LauncherWindowCandidate");var items=Array.CreateInstance(candidate,windows.Length);for(int i=0;i<windows.Length;i++)items.SetValue(windows[i],i);var method=type.GetMethod("SelectAndActivate",BindingFlags.Static|BindingFlags.NonPublic);object restoreCall=restore,foregroundCall=foreground;if(method.GetParameters()[3].ParameterType==typeof(Action<IntPtr>)){restoreCall=new Action<IntPtr>(h=>{restore(h);});foregroundCall=new Action<IntPtr>(h=>{foreground(h);});}return (bool)method.Invoke(null,new object[]{root,items,verify,restoreCall,foregroundCall});}
  static void Windows(string root){string current=Path.Combine(root,"current"),other=Path.Combine(fixture,"other","current");Directory.CreateDirectory(current);Directory.CreateDirectory(other);string expected=Path.Combine(current,"橙子启动器.exe"),foreign=Path.Combine(other,"橙子启动器.exe");File.WriteAllText(expected,"owned image identity fixture");File.WriteAllText(foreign,"another installation");int restored=0,focused=0;Func<IntPtr,bool> restore=h=>{Check(h==new IntPtr(44),"restore addresses only matching window");restored++;return true;};Func<IntPtr,bool> focus=h=>{Check(h==new IntPtr(44),"foreground request addresses only matching window");focused++;return true;};
   var wrong=new[]{Window(123,foreign,45,true,true,"OZL"),Window(123,expected,46,false,true,"OZL"),Window(123,expected,47,true,true,"unrelated"),Window(0,expected,48,true,true,"OZL"),Window(Process.GetCurrentProcess().Id,expected,49,true,true,"OZL"),Window(123,expected,0,true,true,"OZL")};Check(!Activate(root,wrong,w=>true,restore,focus)&&restored==0&&focused==0,"foreign installation hidden worker unrelated title invalid handle and current PID are never activated");
   var good=new[]{Window(123,expected,44,true,true,"OZL")};Check(!Activate(root,good,w=>false,restore,focus)&&restored==0&&focused==0,"changed process or window ownership prevents activation");Check(Activate(root,good,w=>true,restore,focus)&&restored==1&&focused==1,"matching old launcher is restored and receives foreground request");restored=focused=0;Check(Activate(root,new[]{Window(123,expected,44,true,false,"OZL")},w=>true,restore,focus)&&restored==0&&focused==1,"non-minimized launcher keeps its existing maximized or normal layout");
  }
  static void OsRefusal(string root){string expected=Path.Combine(root,"current","橙子启动器.exe");int restored=0,focused=0;Check(!Activate(root,new[]{Window(123,expected,44,true,true,"OZL")},w=>true,h=>{restored++;return false;},h=>{focused++;return true;})&&restored==1&&focused==0,"OS restore refusal is not reported as activation and never requests foreground");restored=focused=0;Check(!Activate(root,new[]{Window(123,expected,44,true,false,"OZL")},w=>true,h=>{restored++;return true;},h=>{focused++;return false;})&&restored==0&&focused==1,"OS foreground refusal is returned as failure rather than silent success");}
  static bool OtherThreadCanAcquire(string root){bool result=false;var thread=new Thread(()=>{IDisposable lease;result=Try(root,out lease);if(lease!=null)lease.Dispose();});thread.Start();Check(thread.Join(2000),"independent lock probe finishes");return result;}
  static void CleanupAndAbandon(string root){Check(Run(root,()=>{Check(!OtherThreadCanAcquire(root),"normal startup holds lease for entire UI lifetime");return 13;},()=>false,message=>{throw new Exception("unexpected notice");})==13,"normal UI result is preserved");Check(OtherThreadCanAcquire(root),"normal UI return releases lease for another thread");bool failed=false;try{Run(root,()=>{throw new InvalidOperationException("owned startup failure");},()=>false,message=>{});}catch(InvalidOperationException){failed=true;}Check(failed&&OtherThreadCanAcquire(root),"UI failure preserves error and releases instance lease");
   string ready=Path.Combine(fixture,"abandon.ready"),stop=Path.Combine(fixture,"abandon.stop");using(var child=Process.Start(new ProcessStartInfo(typeof(DuplicateLaunchTests).Assembly.Location,"--abandon \""+root+"\" \""+ready+"\" \""+stop+"\""){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden})){Until(()=>File.Exists(ready));File.WriteAllText(stop,"");Check(child.WaitForExit(5000)&&child.ExitCode==0,"owned abandoned-lock process exits normally");IDisposable lease;Check(Try(root,out lease)&&lease!=null,"abandoned instance mutex does not prevent a fresh launch");lease.Dispose();}
  }
  static object Field(object value,string field){return value.GetType().GetField(field,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(value);}
  static void HiddenWindow(){string root=Path.Combine(fixture,"hidden-install"),current=Path.Combine(root,"current");Directory.CreateDirectory(current);string image=Path.Combine(current,"橙子启动器.exe"),ready=Path.Combine(fixture,"hidden.ready"),stop=Path.Combine(fixture,"hidden.stop");File.Copy(typeof(DuplicateLaunchTests).Assembly.Location,image);foreach(string name in new[]{"Velopack.dll","Newtonsoft.Json.dll"}){string source=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,name);if(File.Exists(source))File.Copy(source,Path.Combine(current,name));}using(var child=Process.Start(new ProcessStartInfo(image,"--hidden \""+root+"\" \""+ready+"\" \""+stop+"\""){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden})){try{Until(()=>File.Exists(ready));long handle=long.Parse(File.ReadAllText(ready));var type=typeof(NativeApplyGuard).Assembly.GetType("PZ3D.LauncherWindowActivation");var windows=(System.Collections.IEnumerable)type.GetMethod("Windows",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,null);bool found=false;foreach(var window in windows)if((int)Field(window,"Pid")==child.Id&&(IntPtr)Field(window,"Handle")==new IntPtr(handle)){found=true;Check(!(bool)Field(window,"Visible")&&(string)Field(window,"Title")=="OZL"&&NativeApplyGuard.Canonical((string)Field(window,"Image"))==NativeApplyGuard.Canonical(image),"real hidden top-level window keeps exact child PID image title and hidden state");}Check(found,"production EnumWindows and process-image inventory observe owned hidden child");Check(!(bool)type.GetMethod("TryActivate",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{root}),"production activation ignores actual hidden fixture without touching foreground");Check(!child.HasExited,"window discovery leaves owned process alive");}finally{File.WriteAllText(stop,"");Check(child.WaitForExit(5000)&&child.ExitCode==0,"owned hidden window closes and process exits without termination");}}}
  [STAThread]  public static int Main(string[] args){try{if(args.Length==4&&args[0]=="--hidden"){using(NativeApplyGuard.Instance(args[1]))using(var form=new System.Windows.Forms.Form{Text="OZL",ShowInTaskbar=false}){File.WriteAllText(args[2],form.Handle.ToInt64().ToString());var deadline=DateTime.UtcNow.AddSeconds(40);while(!File.Exists(args[3])&&DateTime.UtcNow<deadline){System.Windows.Forms.Application.DoEvents();Thread.Sleep(20);}}return 0;}if(args.Length==4&&args[0]=="--abandon"){NativeApplyGuard.Instance(args[1]);File.WriteAllText(args[2],"held");var deadline=DateTime.UtcNow.AddSeconds(40);while(!File.Exists(args[3])&&DateTime.UtcNow<deadline)Thread.Sleep(20);Environment.Exit(0);return 0;}if(args.Length==4&&args[0]=="--hold"){using(NativeApplyGuard.Instance(args[1])){File.WriteAllText(args[2],"held");var deadline=DateTime.UtcNow.AddSeconds(40);while(!File.Exists(args[3])&&DateTime.UtcNow<deadline)Thread.Sleep(20);}return 0;}fixture=args[0];Directory.CreateDirectory(fixture);string root=Path.Combine(fixture,"installation");using(var holder=Hold(root,"legacy")){try{var watch=Stopwatch.StartNew();bool rejected=false;try{using(NativeApplyGuard.Instance(root)){} }catch(IOException){rejected=true;}Check(rejected&&watch.ElapsedMilliseconds>=9000,"existing update-worker lease retains bounded ten-second exclusion");IDisposable lease;watch.Restart();Check(!Try(root,out lease)&&lease==null&&watch.ElapsedMilliseconds<1000,"duplicate normal startup returns immediately without an exception");}finally{Stop(holder,"legacy");}}IDisposable acquired;Check(Try(root,out acquired)&&acquired!=null,"normal startup acquires lease after old instance releases");acquired.Dispose();Decisions(root);Windows(root);OsRefusal(root);CleanupAndAbandon(root);HiddenWindow();Console.WriteLine("PASS duplicate launch: "+checks+" checks");return 0;}catch(Exception error){Console.Error.WriteLine(error);return 1;}}
 }
